/**
 * API half of the self-hosted photography contract (ledger TD-09 / CM-08).
 *
 * The temple seed, the store fixtures and the gaushala fixtures still carry the
 * original Wikimedia / Unsplash URLs (and the DB rows cannot be rewritten from
 * here), so the API maps them at the response boundary: any string in a JSON
 * payload that names a self-hosted file becomes the absolute
 * `https://darshya.online/images/...` URL. No DB writes, no seed changes, and a
 * file that is not in the table is returned untouched.
 *
 * The data file is generated by scripts/self-host-images.mjs and is an exact
 * copy of apps/web/lib/self-hosted-images.data.ts (a web test pins that).
 */
import { SELF_HOSTED_COMMONS, SELF_HOSTED_UNSPLASH } from './self-hosted-images.data.js';

const COMMONS_RE = /upload\.wikimedia\.org\/wikipedia\/commons\/(?:thumb\/)?[0-9a-f]\/[0-9a-f]{2}\/([^/?#]+)/;
const UNSPLASH_RE = /images\.unsplash\.com\/(photo-[0-9a-f-]+)/;

/**
 * Unsplash photos that now answer 404 (measured 2026-10-06) and the cleared
 * cow photograph that replaces each. Better a real cow than a broken card.
 */
const DEAD_UNSPLASH: Readonly<Record<string, string>> = {
  'photo-1527153907836-a9a0438ff035': '/images/gaushala/cow-field.webp',
  'photo-1551649001-10ff42f27a1b': '/images/gaushala/gir-cow.webp',
};

export function assetOrigin(): string {
  return (process.env.ASSET_ORIGIN ?? 'https://darshya.online').replace(/\/+$/, '');
}

function decode(s: string): string {
  try {
    return decodeURIComponent(s);
  } catch {
    return s;
  }
}

/** Absolute self-hosted URL for a remote photo URL, or undefined if it is not hosted. */
export function selfHostedUrl(url: string): string | undefined {
  const c = COMMONS_RE.exec(url);
  if (c) {
    const e = SELF_HOSTED_COMMONS[decode(c[1]!)];
    return e ? assetOrigin() + e.path : undefined;
  }
  const u = UNSPLASH_RE.exec(url);
  if (u) {
    const e = SELF_HOSTED_UNSPLASH[u[1]!];
    if (e) return assetOrigin() + e.path;
    const dead = DEAD_UNSPLASH[u[1]!];
    return dead ? assetOrigin() + dead : undefined;
  }
  return undefined;
}

/** `https://...` string -> self-hosted URL when mapped; every other value is returned as is. */
export function localizeImageUrl(url: string): string {
  if (url.length < 30 || !url.startsWith('http')) return url;
  return selfHostedUrl(url) ?? url;
}

/**
 * Deep-map a JSON-shaped payload. Returns the SAME reference when nothing
 * changed, otherwise a copy (inputs are never mutated: payloads can be shared
 * with in-memory fixtures). Only plain objects and arrays are walked.
 */
export function localizeImages<T>(value: T): T {
  if (typeof value === 'string') return localizeImageUrl(value) as unknown as T;
  if (Array.isArray(value)) {
    let out: unknown[] | undefined;
    for (let i = 0; i < value.length; i++) {
      const next = localizeImages(value[i]);
      if (next !== value[i]) {
        out ??= value.slice();
        out[i] = next;
      }
    }
    return (out ?? value) as T;
  }
  if (value !== null && typeof value === 'object' && Object.getPrototypeOf(value) === Object.prototype) {
    let out: Record<string, unknown> | undefined;
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      const next = localizeImages(v);
      if (next !== v) {
        out ??= { ...(value as Record<string, unknown>) };
        out[k] = next;
      }
    }
    return (out ?? value) as T;
  }
  return value;
}
